def is_scalar_field(field: Field) -> bool:
    is_scalar = (
        field.shape == Shape.SINGLETON
        and not lenient_issubclass(field.type_, BaseModel)
        and not lenient_issubclass(field.type_, sequence_types + (dict,))
    )

    # If field is a Union, we should handle its subfields accordingly
    if hasattr(field, 'sub_fields') and field.sub_fields:
        return is_scalar and all(is_scalar_field(f) for f in field.sub_fields)

    return is_scalar and not isinstance(field.schema, params.Body)
```

